<?php
declare(strict_types=1);require_once dirname(__DIR__).'/config/bootstrap.php';require_permission('suppliers.view');$id=(int)($_GET['id']??0);$st=db()->prepare('SELECT * FROM suppliers WHERE id=:id');$st->execute([':id'=>$id]);$s=$st->fetch();if(!$s){flash('error','Supplier not found.');redirect('suppliers/index');}$pu=db()->prepare('SELECT id,purchase_no,purchase_date,status,total_amount,balance_due FROM purchases WHERE supplier_id=:id ORDER BY id DESC LIMIT 10');$pu->execute([':id'=>$id]);$purchases=$pu->fetchAll();$pr=db()->prepare('SELECT id,name,sku,current_stock FROM products WHERE default_supplier_id=:id ORDER BY name LIMIT 10');$pr->execute([':id'=>$id]);$products=$pr->fetchAll();$pageTitle=$s['name'];$pageStyles=['admin.css','commerce.css'];require BASE_PATH.'/includes/header.php';require BASE_PATH.'/includes/sidebar.php';?>
<div class="app-main"><?php require BASE_PATH.'/includes/navbar.php';?><main class="content"><?php require BASE_PATH.'/includes/alerts.php';?><div class="page-toolbar"><div><a class="back-link" href="<?=e(app_url('suppliers/index'))?>">← Suppliers</a><h2><?=e($s['name'])?></h2><p><?=e($s['contact_person']?:'Supplier account')?></p></div><div class="toolbar-actions"><?php if(user_can('purchases.create')):?><a class="button button--secondary" href="<?=e(app_url('purchases/add?supplier='.$id))?>">New purchase</a><?php endif;?><?php if(user_can('suppliers.manage')):?><a class="button button--primary" href="<?=e(app_url('suppliers/edit?id='.$id))?>">Edit supplier</a><?php endif;?></div></div>
<section class="detail-two-column"><article class="panel-card detail-card"><div class="panel-card__header"><h3>Contact details</h3></div><dl class="detail-list"><div><dt>Phone</dt><dd><?=e($s['phone']?:'—')?></dd></div><div><dt>Alternate</dt><dd><?=e($s['alternate_phone']?:'—')?></dd></div><div><dt>Email</dt><dd><?=e($s['email']?:'—')?></dd></div><div><dt>Tax / PIN</dt><dd><?=e($s['tax_number']?:'—')?></dd></div><div><dt>Address</dt><dd><?=e($s['address']?:'—')?></dd></div></dl></article><article class="panel-card"><div class="panel-card__header"><h3>Default products</h3></div><div class="simple-list"><?php if(!$products):?><div class="empty-state compact"><strong>No linked products</strong></div><?php else:foreach($products as$p):?><a class="simple-list__row row-link" href="<?=e(app_url('products/view?id='.(int)$p['id']))?>"><div><strong><?=e($p['name'])?></strong><span><?=e($p['sku'])?></span></div><b><?=e(format_quantity($p['current_stock']))?></b></a><?php endforeach;endif;?></div></article></section>
<section class="panel-card table-panel section-gap"><div class="panel-card__header"><h3>Recent purchases</h3></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Purchase</th><th>Date</th><th>Status</th><th>Total</th><th>Balance</th></tr></thead><tbody><?php if(!$purchases):?><tr><td colspan="5"><div class="empty-state compact"><strong>No purchases yet</strong></div></td></tr><?php else:foreach($purchases as$p):?><tr><td><a class="table-action" href="<?=e(app_url('purchases/view?id='.(int)$p['id']))?>"><?=e($p['purchase_no'])?></a></td><td><?=e(format_datetime($p['purchase_date'],'d M Y'))?></td><td><?=e(ucwords(str_replace('_',' ',$p['status'])))?></td><td><?=e(money($p['total_amount']))?></td><td><?=e(money($p['balance_due']))?></td></tr><?php endforeach;endif;?></tbody></table></div></section>
</main></div><?php require BASE_PATH.'/includes/footer.php';?>
